// Las fotos de cada tratamiento. Cambia las URL por las de tu clínica:
// tienen que ser públicas (https://) y JPG o PNG, de hasta 5 MB.
// La clave (blanqueamiento, ortodoncia…) es la opción que elige Sofía:
// tiene que coincidir con las «Opciones» del dato en el CRM.
const FOTOS = {
  blanqueamiento: {
    url: 'https://clinicasonrisaperfecta.site/media/fotos/blanqueamiento.jpg',
    pie: 'Blanqueamiento en Sonrisa Perfecta',
  },
  ortodoncia: {
    url: 'https://clinicasonrisaperfecta.site/media/fotos/ortodoncia.jpg',
    pie: 'Ortodoncia en Sonrisa Perfecta',
  },
  implantes: {
    url: 'https://clinicasonrisaperfecta.site/media/fotos/implantes.jpg',
    pie: 'Implantes en Sonrisa Perfecta',
  },
};

// Lo que manda el CRM llega en el cuerpo del webhook.
const llamada = $input.first().json.body || {};
const sinAcentos = (t) => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const pedido = sinAcentos(llamada.args?.tratamiento);
const foto = FOTOS[pedido];

if (!pedido) {
  return [{ json: { resultado: `No me dijeron de qué tratamiento. Tengo fotos de: ${Object.keys(FOTOS).join(', ')}.` } }];
}
if (!foto) {
  // Sin archivo: Sofía lee esto y se lo explica al paciente.
  return [{ json: { resultado: `No tengo fotos de «${pedido}». Tengo de: ${Object.keys(FOTOS).join(', ')}.` } }];
}

// `resultado` es lo que lee Sofía; `archivos`, lo que el CRM le manda al paciente.
return [{
  json: {
    resultado: `Listo: el CRM le manda al paciente una foto de ${pedido}.`,
    archivos: [{ tipo: 'imagen', url: foto.url, pie: foto.pie, nombre: `${pedido}.jpg` }],
  },
}];
